+import { assertEquals } from "jsr:@std/assert";
+import { World } from "../src/lib/ecs-js/index.js";
+import { Equipment } from "../src/rules/components/Equipment.js";
+import { Encumbrance } from "../src/rules/components/Encumbrance.js";
