function collectSubtree(world, rootId, seen, out) {
  const id = Number(rootId || 0) | 0;
  if (!(id > 0) || seen.has(id) || !world.isAlive?.(id)) return;
  seen.add(id);
  out.push(id);
  for (const childId of children(world, id)) {
