/**
 * Resolve final damage after applying type-based resistances.
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} targetId
 * @param {number} rawAmount
 * @param {string} type
 * @param {number} [armorPenetration=0]
 * @returns {number}
